      "rationale": "With a solid understanding of instructional design models, this course explores learning theories, which is essential for creating assessments that promote deeper understanding and retention."
    },
    {
      "step": 4,
      "course_id": "EDX779",
      "rationale": "This course provides strategies for analyzing what an assessment is evaluating, which is critical for measuring student learning and making instructional decisions."
    },
    {
      "step": 5,
      "course_id": "EDX2200",
      "rationale": "By analyzing multidimensional student data and making instructional decisions based on evidence of student progress and needs, this course helps learners create effective assessments."
    },
    {
      "step": 6,
      "course_id": "EDX2065",
      "rationale": "This course enables learners to embed a performance assessment into an instructional sequence, collect pilot data, and analyze it to evaluate whether it meets SNAP quality criteria."
    }
  ]
}

